/bin/bash -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="Find your space for better notes. Compare Marginalia Starter, Pro, and Team plans, starting free.">
  <meta name="theme-color" content="#f8f8f3">
  <title>Pricing — Marginalia</title>
  <style>
    :root {
      --canvas: #f8f8f3;
      --surface: #ffffff;
      --text: #252c28;
      --muted: #62695f;
      --line: #d9ded4;
      --control-border: #7b8677;
      --accent: #285442;
      --accent-hover: #1c4031;
      --accent-soft: #eef2e9;
      --accent-line: #a7b99c;
      --on-accent: #ffffff;
      --space-1: 4px;
      --space-2: 8px;
      --space-3: 12px;
      --space-4: 16px;
      --space-6: 24px;
      --space-8: 32px;
      --space-12: 48px;
      --space-16: 64px;
      --space-24: 96px;
      --text-xs: .75rem;
      --text-sm: .875rem;
      --text-base: 1rem;
      --text-lg: 1.125rem;
      --text-xl: 1.5rem;
      --text-heading: 2.5rem;
      --text-price: 3rem;
      --text-display: clamp(2.5rem, 4.5vw, 4rem);
      --radius: 8px;
      --radius-small: 4px;
      --font-body: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      --font-editorial: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
      --transition: 160ms ease-out;
    }
    * { box-sizing: border-box; }
    body { margin: 0; background: var(--canvas); color: var(--text); font: var(--text-base)/1.5 var(--font-body); -webkit-font-smoothing: antialiased; }
    a { color: inherit; }
    button { font: inherit; cursor: pointer; }
    button, a, summary { -webkit-tap-highlight-color: transparent; }
    a, button, summary { transition: color var(--transition), background-color var(--transition), border-color var(--transition); }
    :focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }
    h1, h2, h3, p { margin: 0; }
    h1, h2, h3 { text-wrap: balance; }
    .container { width: min(1120px, calc(100% - var(--space-16))); margin-inline: auto; }
    .skip-link { position: absolute; top: -80px; left: var(--space-4); z-index: 2; padding: var(--space-3) var(--space-4); background: var(--accent); color: var(--on-accent); }
    .skip-link:focus { top: var(--space-4); }
    .site-header { border-bottom: 1px solid var(--line); }
    .header-inner { min-height: 88px; display: flex; align-items: center; gap: var(--space-12); }
    .brand { display: inline-flex; align-items: center; gap: var(--space-3); text-decoration: none; font: 600 var(--text-xl)/1.2 var(--font-editorial); letter-spacing: -.04em; white-space: nowrap; }
    .brand-mark { width: 28px; height: 32px; color: var(--accent); flex: none; }
    .nav-links { display: flex; align-items: center; gap: var(--space-8); margin-left: auto; }
    .nav-links a { display: inline-flex; align-items: center; min-height: 44px; text-decoration: none; font-size: var(--text-sm); color: var(--muted); }
    .nav-links a:hover, .nav-links a[aria-current] { color: var(--text); }
    .nav-links a[aria-current] { text-decoration: underline; text-underline-offset: 8px; text-decoration-color: var(--accent); }
    .account-links { display: flex; gap: var(--space-6); align-items: center; }
    .login { display: inline-flex; align-items: center; min-height: 44px; text-decoration: none; font-size: var(--text-sm); }
    .login:hover { color: var(--accent); text-decoration: underline; }
    .button { min-height: 48px; display: inline-flex; align-items: center; justify-content: center; gap: var(--space-3); border: 1px solid var(--control-border); border-radius: var(--radius-small); padding: var(--space-3) var(--space-6); color: var(--text); text-decoration: none; font-size: var(--text-sm); font-weight: 600; line-height: 1.5; }
    .button:hover { background: var(--accent-soft); border-color: var(--accent); }
    .button:active { background: var(--line); }
    .button-primary { background: var(--accent); color: var(--on-accent); border-color: var(--accent); }
    .button-primary:hover, .button-primary:active { background: var(--accent-hover); border-color: var(--accent-hover); }
    .header-cta { min-height: 44px; padding: var(--space-2) var(--space-4); }
    .hero { padding-top: var(--space-16); padding-bottom: var(--space-12); }
    .eyebrow { display: flex; align-items: center; gap: var(--space-3); color: var(--accent); font-size: var(--text-xs); font-weight: 600; letter-spacing: .12em; text-transform: uppercase; margin-bottom: var(--space-6); }
    .eyebrow::before { content: ""; width: 24px; height: 1px; background: currentColor; }
    .hero-layout { display: grid; grid-template-columns: 1.4fr 1fr; align-items: end; gap: var(--space-16); }
    h1 { font: 400 var(--text-display)/1.08 var(--font-editorial); letter-spacing: -.045em; }
    h1 em { font-weight: 400; color: var(--accent); }
    .hero-copy { max-width: 36ch; padding-bottom: var(--space-1); color: var(--muted); font-size: var(--text-lg); line-height: 1.65; }
    .billing-row { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); margin-top: var(--space-12); }
    .billing-control { display: flex; align-items: center; gap: var(--space-4); flex-wrap: wrap; }
    .billing-toggle { display: inline-flex; padding: var(--space-1); border: 1px solid var(--control-border); border-radius: var(--radius); }
    .billing-toggle button { min-height: 44px; padding: var(--space-2) var(--space-6); border: 0; border-radius: var(--radius-small); background: transparent; color: var(--muted); font-size: var(--text-sm); }
    .billing-toggle button:hover { color: var(--accent); background: var(--accent-soft); }
    .billing-toggle button[aria-pressed="true"] { color: var(--on-accent); background: var(--accent); }
    .savings { font-size: var(--text-sm); color: var(--accent); }
    .billing-note { font-size: var(--text-sm); color: var(--muted); }
    .plans { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-4); }
    .plan { display: flex; flex-direction: column; padding: var(--space-8); background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); }
    .plan-featured { background: var(--accent-soft); border-color: var(--accent-line); position: relative; }
    .plan-featured::before { content: ""; position: absolute; height: 3px; top: -1px; left: var(--space-2); right: var(--space-2); background: var(--accent); border-radius: 0 0 var(--radius-small) var(--radius-small); }
    .plan-title { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); min-height: 32px; }
    .plan h2 { font-size: var(--text-xl); font-weight: 600; letter-spacing: -.035em; }
    .recommended { font-size: var(--text-xs); color: var(--accent); background: var(--surface); padding: var(--space-1) var(--space-2); border-radius: var(--radius-small); white-space: nowrap; }
    .plan-description { color: var(--muted); font-size: var(--text-sm); margin-top: var(--space-2); }
    .price { display: flex; align-items: baseline; gap: var(--space-2); margin-top: var(--space-8); font-variant-numeric: tabular-nums; }
    .amount { font-size: var(--text-price); font-weight: 500; letter-spacing: -.06em; line-height: 1.2; }
    .price-unit { color: var(--muted); font-size: var(--text-sm); }
    .billing-detail { min-height: 24px; margin-top: var(--space-1); font-size: var(--text-xs); color: var(--muted); }
    .plan .button { width: 100%; margin-top: var(--space-6); }
    .button-arrow { margin-left: auto; font-size: var(--text-lg); line-height: 1; }
    .feature-list { list-style: none; padding: var(--space-6) 0 0; margin: var(--space-6) 0 0; border-top: 1px solid var(--line); display: grid; gap: var(--space-4); font-size: var(--text-sm); }
    .feature-list li { display: flex; align-items: baseline; gap: var(--space-3); }
    .feature-list li::before { content: "✓"; color: var(--accent); flex: 0 0 16px; font-weight: 600; }
    .feature-list li.unavailable { color: var(--muted); }
    .feature-list li.unavailable::before { content: "−"; color: var(--muted); font-weight: 400; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
    .trial-note { text-align: center; margin-top: var(--space-6); color: var(--muted); font-size: var(--text-sm); }
    .trial-note span { color: var(--accent); margin-right: var(--space-2); }
    .features { padding-block: var(--space-24); }
    .section-label { color: var(--muted); font-size: var(--text-xs); letter-spacing: .1em; text-transform: uppercase; font-weight: 600; }
    .feature-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-12); margin-top: var(--space-8); }
    .feature { border-top: 1px solid var(--line); padding-top: var(--space-6); }
    .feature-icon { width: 24px; height: 24px; display: block; color: var(--accent); margin-bottom: var(--space-4); }
    .feature h3 { font-size: var(--text-base); font-weight: 600; }
    .feature p { color: var(--muted); font-size: var(--text-sm); line-height: 1.7; margin-top: var(--space-2); max-width: 32ch; }
    .faq { display: grid; grid-template-columns: 1fr 1.6fr; gap: var(--space-16); border-top: 1px solid var(--line); padding-block: var(--space-16) var(--space-24); }
    .faq h2 { font: 400 var(--text-heading)/1.15 var(--font-editorial); letter-spacing: -.035em; }
    .faq-intro { margin-top: var(--space-4); color: var(--muted); font-size: var(--text-sm); }
    .faq-list { border-top: 1px solid var(--line); }
    details { border-bottom: 1px solid var(--line); }
    summary { list-style: none; cursor: pointer; padding: var(--space-6) 0; display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); font-size: var(--text-base); font-weight: 500; }
    summary::-webkit-details-marker { display: none; }
    summary::after { content: "+"; font-size: var(--text-xl); color: var(--accent); font-weight: 400; line-height: 1; }
    details[open] summary::after { content: "−"; }
    summary:hover { color: var(--accent); }
    details p { color: var(--muted); font-size: var(--text-sm); line-height: 1.75; max-width: 60ch; padding: 0 var(--space-8) var(--space-6) 0; }
    .site-footer { border-top: 1px solid var(--line); }
    .footer-inner { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); padding-block: var(--space-8); }
    .footer-brand { font-size: var(--text-lg); }
    .footer-inner p { color: var(--muted); font-size: var(--text-xs); }
    @media (max-width: 1000px) {
      .header-inner { gap: var(--space-6); }
      .nav-links { gap: var(--space-6); }
      .account-links { gap: var(--space-4); }
      .plan { padding: var(--space-6); }
      .plan-title { flex-wrap: wrap; align-content: start; min-height: 64px; }
      .hero-layout { gap: var(--space-8); }
      .feature-grid { gap: var(--space-8); }
    }
    @media (max-width: 760px) {
      .container { width: calc(100% - var(--space-12)); }
      .header-inner { min-height: 80px; flex-wrap: wrap; justify-content: space-between; gap: 0 var(--space-4); padding-top: var(--space-4); }
      .brand { font-size: var(--text-xl); }
      .account-links { margin-left: auto; }
      .login { display: none; }
      .nav-links { order: 3; width: 100%; justify-content: center; gap: var(--space-8); margin: var(--space-2) 0 0; }
      .nav-links a { min-height: 48px; }
      .hero { padding-block: var(--space-12) var(--space-8); }
      .hero-layout { grid-template-columns: 1fr; gap: var(--space-6); }
      .hero-copy { font-size: var(--text-base); max-width: 42ch; }
      .billing-row { margin-top: var(--space-8); flex-direction: column; align-items: start; gap: var(--space-4); }
      .billing-toggle button { padding-inline: var(--space-4); }
      .plans { grid-template-columns: 1fr; gap: var(--space-6); }
      .plan { padding: var(--space-8); }
      .plan-title { min-height: 32px; }
      .features { padding-block: var(--space-16); }
      .feature-grid { grid-template-columns: 1fr; gap: var(--space-8); }
      .feature { display: grid; grid-template-columns: 24px 1fr; column-gap: var(--space-4); }
      .feature-icon { grid-row: span 2; margin: 0; }
      .feature p { max-width: 45ch; }
      .faq { grid-template-columns: 1fr; gap: var(--space-8); padding-block: var(--space-12) var(--space-16); }
      .faq h2 { font-size: 2rem; }
      .footer-inner { align-items: start; flex-direction: column; gap: var(--space-3); }
    }
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { transition: none !important; }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>
  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="#" aria-label="Marginalia home">
        <svg class="brand-mark" viewBox="0 0 28 32" fill="none" aria-hidden="true"><path d="M4 3h20v26H4z" stroke="currentColor" stroke-width="1.5"/><path d="M9 3v26M13 11h7M13 16h7M13 21h4" stroke="currentColor" stroke-width="1.5"/></svg>
        Marginalia
      </a>
      <nav class="nav-links" aria-label="Main navigation">
        <a href="#features">Features</a>
        <a href="#pricing" aria-current="page">Pricing</a>
        <a href="#faq">FAQs</a>
      </nav>
      <div class="account-links">
        <a class="login" href="#">Log in</a>
        <a class="button header-cta" href="#">Sign up free <span aria-hidden="true">↗</span></a>
      </div>
    </div>
  </header>

  <main id="main">
    <section class="container" id="pricing" aria-labelledby="pricing-heading">
      <div class="hero">
        <p class="eyebrow">Plans & pricing</p>
        <div class="hero-layout">
          <h1 id="pricing-heading">Room for every<br><em>train of thought.</em></h1>
          <p class="hero-copy">A place for your notes, ideas, and everything in between. Start free, or find a plan that gives you more room to think.</p>
        </div>
        <div class="billing-row">
          <div class="billing-control">
            <div class="billing-toggle" role="group" aria-label="Billing period">
              <button type="button" data-billing="monthly" aria-pressed="true">Monthly</button>
              <button type="button" data-billing="yearly" aria-pressed="false">Yearly</button>
            </div>
            <span class="savings">Save 20% yearly</span>
          </div>
          <p class="billing-note">A plan for your own pace.</p>
        </div>
      </div>

      <div class="plans">
        <article class="plan" aria-labelledby="starter-title">
          <div class="plan-title"><h2 id="starter-title">Starter</h2></div>
          <p class="plan-description">For your first notes and everyday ideas.</p>
          <div class="price"><span class="amount">$0</span><span class="price-unit">/ month</span></div>
          <p class="billing-detail">Free, for as long as you like.</p>
          <a class="button" href="#">Start for free <span class="button-arrow" aria-hidden="true">↗</span></a>
          <ul class="feature-list">
            <li>Up to 100 notes</li>
            <li>Sync across 2 devices</li>
            <li>Basic search</li>
            <li class="unavailable"><span class="sr-only">Not included: </span>Offline access</li>
            <li class="unavailable"><span class="sr-only">Not included: </span>Shared notebooks</li>
          </ul>
        </article>
        <article class="plan plan-featured" aria-labelledby="pro-title">
          <div class="plan-title"><h2 id="pro-title">Pro</h2><span class="recommended">Most popular</span></div>
          <p class="plan-description">For a growing world of thoughts.</p>
          <div class="price"><span class="amount" id="pro-price">$8</span><span class="price-unit">/ month</span></div>
          <p class="billing-detail" id="pro-billing">Billed monthly.</p>
          <a class="button button-primary" href="#">Try Pro for free <span class="button-arrow" aria-hidden="true">↗</span></a>
          <ul class="feature-list">
            <li>Unlimited notes</li>
            <li>Sync across unlimited devices</li>
            <li>Full-text search inside PDFs</li>
            <li>Offline access</li>
            <li class="unavailable"><span class="sr-only">Not included: </span>Shared notebooks</li>
          </ul>
        </article>
        <article class="plan" aria-labelledby="team-title">
          <div class="plan-title"><h2 id="team-title">Team</h2></div>
          <p class="plan-description">For ideas that are better together.</p>
          <div class="price"><span class="amount" id="team-price">$14</span><span class="price-unit">/ user / month</span></div>
          <p class="billing-detail" id="team-billing">Billed monthly, per user.</p>
          <a class="button" href="#">Get started with Team <span class="button-arrow" aria-hidden="true">↗</span></a>
          <ul class="feature-list">
            <li>Everything in Pro</li>
            <li>Shared notebooks</li>
            <li>Admin controls</li>
            <li>Priority support</li>
            <li>Single sign-on (SSO)</li>
          </ul>
        </article>
      </div>
      <p class="trial-note"><span aria-hidden="true">✓</span> Try Pro free for 14 days. No credit card required.</p>
      <p class="sr-only" id="billing-announcement" role="status" aria-atomic="true"></p>
    </section>

    <section class="container features" id="features" aria-labelledby="features-heading">
      <h2 class="section-label" id="features-heading">Thoughtfully built, whichever plan you choose</h2>
      <div class="feature-grid">
        <div class="feature">
          <svg class="feature-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5M8 10.5h5"/></svg>
          <h3>Find your train of thought</h3>
          <p>Fast search brings the note you need back into focus.</p>
        </div>
        <div class="feature">
          <svg class="feature-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/></svg>
          <h3>Your notes, kept safe</h3>
          <p>Encryption keeps your notes and the ideas inside them secure.</p>
        </div>
        <div class="feature">
          <svg class="feature-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/></svg>
          <h3>Pick up where you left off</h3>
          <p>Your notes stay in sync across your connected devices.</p>
        </div>
      </div>
    </section>

    <section class="container faq" id="faq" aria-labelledby="faq-heading">
      <div>
        <h2 id="faq-heading">A few things<br>you might be wondering.</h2>
        <p class="faq-intro">The details, before you decide.</p>
      </div>
      <div class="faq-list">
        <details open>
          <summary>Can I cancel anytime?</summary>
          <p>Yes. You can cancel your subscription at any time, with no questions asked.</p>
        </details>
        <details>
          <summary>Is there a free trial for Pro?</summary>
          <p>Yes. Pro comes with a 14-day free trial. No credit card required.</p>
        </details>
        <details>
          <summary>Do you offer student discounts?</summary>
          <p>Yes. Students get 50% off Pro with a valid school email.</p>
        </details>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <a class="brand footer-brand" href="#">Marginalia</a>
      <p>© 2026 Marginalia Inc. All rights reserved.</p>
    </div>
  </footer>
  <script>
    const billingButtons = document.querySelectorAll('"'[data-billing]');
    const billingRates = {
      monthly: { pro: '"'$8'"', team: '"'$14'"', proDetail: 'Billed monthly.', teamDetail: 'Billed monthly, per user.' },
      yearly: { pro: '"'$6.40'"', team: '"'$11.20'"', proDetail: '"'$76.80 billed yearly.'"', teamDetail: '"'$134.40 billed yearly, per user.'"' }
    };

    billingButtons.forEach(button => {
      button.addEventListener('click', () => {
        const period = button.dataset.billing;
        const rates = billingRates[period];
        billingButtons.forEach(option => option.setAttribute('aria-pressed', String(option === button)));
        document.getElementById('pro-price').textContent = rates.pro;
        document.getElementById('team-price').textContent = rates.team;
        document.getElementById('pro-billing').textContent = rates.proDetail;
        document.getElementById('team-billing').textContent = rates.teamDetail;
        document.getElementById('billing-announcement').textContent = "'`${period === '"'yearly' ? 'Yearly' : 'Monthly'} billing selected. Pro: "'${rates.pro} per month. ${rates.proDetail} Team: ${rates.team} per user per month. ${rates.teamDetail}`;
      });
    });
  </script>
</body>
</html>
EOF'

