from html.parser import HTMLParser
from pathlib import Path
class PageCheck(HTMLParser):
 def __init__(self):
  super().__init__(convert_charrefs=True)
  self.stack=[]; self.ids=set(); self.anchors=[]; self.h1=0
 def handle_starttag(self, tag, attrs):
  attrs=dict(attrs)
  if 'id' in attrs:
   assert attrs['id'] not in self.ids, 'Duplicate id: '+attrs['id']
   self.ids.add(attrs['id'])
  if tag=='a' and attrs.get('href','').startswith('#') and len(attrs['href'])>1:
   self.anchors.append(attrs['href'][1:])
  if tag=='h1': self.h1+=1
  if tag not in {'meta','link','br','hr','img','input','source','area','base','embed','param','track','wbr'}:
   self.stack.append(tag)
 def handle_endtag(self, tag):
  assert self.stack and self.stack[-1]==tag, 'Mismatched tag: '+tag
  self.stack.pop()
p=PageCheck(); p.feed(Path('index.html').read_text())
assert not p.stack, p.stack
assert p.h1==1
assert all(a in p.ids for a in p.anchors)
print('HTML structure, unique ids, heading, and section links passed.')
