const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const source = fs.readFileSync('index.html', 'utf8').match(/<script>([\\s\\S]*?)<\\/script>/)[1];
const fields = Object.fromEntries(['pro-price', 'team-price', 'pro-billing', 'team-billing', 'billing-announcement'].map(id => [id, {textContent: ''}]));
const buttons = ['monthly','yearly'].map(period => ({dataset:{billing:period}, attrs:{}, setAttribute(key,value){ this.attrs[key]=value; }, addEventListener(type,callback){ this.click=callback; }}));
vm.runInNewContext(source, {document:{querySelectorAll:()=>buttons,getElementById:id=>fields[id]}});
for (const period of ['yearly','monthly','yearly']) {
 const selected=buttons.find(button=>button.dataset.billing===period);
 selected.click();
 assert.equal(selected.attrs['aria-pressed'], 'true');
 assert.equal(buttons.find(button=>button"'!==selected).attrs['"'aria-pressed'], 'false');
 assert.equal(fields['pro-price'].textContent, period==='yearly'?'"'$6.40'"':'"'$8'"');
 assert.equal(fields['team-price'].textContent, period==='yearly'?'"'$11.20'"':'"'$14'"');
 assert.ok(fields['billing-announcement'].textContent.includes(period==='yearly'?'Yearly':'Monthly'));
}
assert.equal(fields['pro-billing'].textContent,'"'$76.80 billed yearly.'"');
assert.equal(fields['team-billing'].textContent,'"'$134.40 billed yearly, per user.'"');
assert.equal((8*.8*12).toFixed(2),'76.80');
assert.equal((14*.8*12).toFixed(2),'134.40');
console.log('Billing toggle, annual discount math, selected states, and screen-reader announcements passed.');
